     1	package com.fream.back.domain.warehouseStorage.service.command;
     2	
     3	import com.fream.back.domain.order.entity.Order;
     4	import com.fream.back.domain.sale.entity.Sale;
     5	import com.fream.back.domain.user.entity.User;
     6	import com.fream.back.domain.warehouseStorage.entity.WarehouseStatus;
     7	import com.fream.back.domain.warehouseStorage.entity.WarehouseStorage;
     8	import com.fream.back.domain.warehouseStorage.exception.*;
     9	import com.fream.back.domain.warehouseStorage.repository.WarehouseStorageRepository;
    10	import com.fream.back.domain.warehouseStorage.service.query.WarehouseStorageQueryService;
    11	import lombok.RequiredArgsConstructor;
    12	import org.springframework.stereotype.Service;
    13	import org.springframework.transaction.annotation.Transactional;
    14	
    15	import java.time.LocalDate;
    16	
    17	@Service
    18	@RequiredArgsConstructor
    19	@Transactional
    20	public class WarehouseStorageCommandService {
    21	
    22	    private final WarehouseStorageRepository warehouseStorageRepository;
    23	    private final WarehouseStorageQueryService warehouseStorageQueryService;
    24	
    25	    /**
    26	     * 주문에 대한 창고 보관 정보를 생성합니다.
    27	     *
    28	     * @param order 주문 정보
    29	     * @param user 사용자 정보
    30	     * @return 생성된 창고 보관 정보
    31	     * @throws WarehouseStorageProcessingFailedException 창고 보관 생성 처리 중 오류 발생 시
    32	     */
    33	    public WarehouseStorage createOrderStorage(Order order, User user) {
    34	        try {
    35	            // 입력 유효성 검사
    36	            if (order == null) {
    37	                throw new WarehouseStorageProcessingFailedException("주문 정보가 없습니다.");
    38	            }
    39	            if (user == null) {
    40	                throw new WarehouseStorageProcessingFailedException("사용자 정보가 없습니다.");
    41	            }
    42	
    43	            // 이미 창고 보관 정보가 있는지 확인
    44	            if (order.getWarehouseStorage() != null) {
    45	                throw new WarehouseStorageProcessingFailedException("주문(ID: " + order.getId() + ")에 이미 창고 보관 정보가 있습니다.");
    46	            }
    47	
    48	            WarehouseStorage warehouseStorage = WarehouseStorage.builder()
    49	                    .user(user)
    50	                    .order(order)
    51	                    .storageLocation("Default Location") // 기본 창고 위치
    52	                    .status(WarehouseStatus.IN_STORAGE)
    53	                    .startDate(LocalDate.now())
    54	                    .endDate(LocalDate.now().plusMonths(1)) // 기본 1개월 보관
    55	                    .build();
    56	
    57	            return warehouseStorageRepository.save(warehouseStorage);
    58	        } catch (Exception e) {
    59	            if (e instanceof WarehouseStorageException) {
    60	                throw e;
    61	            }
    62	            throw new WarehouseStorageProcessingFailedException("창고 보관 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
    63	        }
    64	    }
    65	
    66	    /**
    67	     * 판매자의 상품에 대한 창고 보관 정보를 생성합니다.
    68	     *
    69	     * @param sale 판매 정보
    70	     * @param seller 판매자 정보
    71	     * @return 생성된 창고 보관 정보
    72	     * @throws WarehouseStorageProcessingFailedException 창고 보관 생성 처리 중 오류 발생 시
    73	     */
    74	    public WarehouseStorage createSellerStorage(Sale sale, User seller) {
    75	        try {
    76	            // 입력 유효성 검사
    77	            if (sale == null) {
    78	                throw new WarehouseStorageProcessingFailedException("판매 정보가 없습니다.");
    79	            }
    80	            if (seller == null) {
    81	                throw new WarehouseStorageProcessingFailedException("판매자 정보가 없습니다.");
    82	            }
    83	
    84	            // 이미 창고 보관 정보가 있는지 확인
    85	            boolean storageExists = warehouseStorageRepository.findBySale(sale).isPresent();
    86	            if (storageExists) {
    87	                throw new WarehouseStorageProcessingFailedException("판매(ID: " + sale.getId() + ")에 이미 창고 보관 정보가 있습니다.");
    88	            }
    89	
    90	            WarehouseStorage warehouseStorage = WarehouseStorage.builder()
    91	                    .user(seller)
    92	                    .sale(sale)
    93	                    .storageLocation("Seller's Warehouse") // 판매자 창고 위치 설정
    94	                    .status(WarehouseStatus.IN_STORAGE)
    95	                    .startDate(LocalDate.now())
    96	                    .endDate(LocalDate.now().plusMonths(1)) // 기본 1개월 보관
    97	                    .build();
    98	
    99	            return warehouseStorageRepository.save(warehouseStorage);
   100	        } catch (Exception e) {
   101	            if (e instanceof WarehouseStorageException) {
   102	                throw e;
   103	            }
   104	            throw new WarehouseStorageProcessingFailedException("판매자 창고 보관 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
   105	        }
   106	    }
   107	
   108	    /**
   109	     * 판매와 연관된 창고 보관 상태를 업데이트합니다.
   110	     *
   111	     * @param sale 판매 정보
   112	     * @param newStatus 새로운 상태
   113	     * @throws WarehouseStorageNotFoundException 창고 보관 정보를 찾을 수 없을 경우
   114	     * @throws InvalidStatusTransitionException 유효하지 않은 상태 전환일 경우
   115	     */
   116	    @Transactional
   117	    public void updateWarehouseStatus(Sale sale, WarehouseStatus newStatus) {
   118	        try {
   119	            // 입력 유효성 검사
   120	            if (sale == null) {
   121	                throw new WarehouseStorageProcessingFailedException("판매 정보가 없습니다.");
   122	            }
   123	            if (newStatus == null) {
   124	                throw new InvalidWarehouseStatusException("새로운 상태 정보가 없습니다.");
   125	            }
   126	
   127	            WarehouseStorage storage = warehouseStorageQueryService.findBySale(sale);
   128	
   129	            // 상태 전환 유효성 검사
   130	            validateStatusTransition(storage.getStatus(), newStatus);
   131	
   132	            storage.updateStatus(newStatus);
   133	            warehouseStorageRepository.save(storage);
   134	        } catch (Exception e) {
   135	            if (e instanceof WarehouseStorageException) {
   136	                throw e;
   137	            }
   138	            throw new WarehouseStorageProcessingFailedException("창고 보관 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
   139	        }
   140	    }
   141	
   142	    /**
   143	     * 판매와 연관된 창고 보관 상태를 판매 완료로 업데이트합니다.
   144	     *
   145	     * @param sale 판매 정보
   146	     * @throws WarehouseStorageNotFoundException 창고 보관 정보를 찾을 수 없을 경우
   147	     * @throws InvalidStatusTransitionException 유효하지 않은 상태 전환일 경우
   148	     */
   149	    @Transactional
   150	    public void updateWarehouseStatusToSold(Sale sale) {
   151	        if (sale == null) {
   152	            throw new WarehouseStorageProcessingFailedException("판매 정보가 없습니다.");
   153	        }
   154	
   155	        if (sale.isWarehouseStorage()) {
   156	            try {
   157	                WarehouseStorage storage = warehouseStorageQueryService.findBySale(sale);
   158	
   159	                // 이미 판매된 상품인지 확인
   160	                if (storage.getStatus() == WarehouseStatus.SOLD) {
   161	                    throw new InvalidStatusTransitionException("이미 판매 완료 상태인 상품입니다(ID: " + sale.getId() + ")");
   162	                }
   163	
   164	                // 상태 전환 유효성 검사
   165	                validateStatusTransition(storage.getStatus(), WarehouseStatus.SOLD);
   166	
   167	                storage.updateStatus(WarehouseStatus.SOLD);
   168	                warehouseStorageRepository.save(storage);
   169	            } catch (Exception e) {
   170	                if (e instanceof WarehouseStorageException) {
   171	                    throw e;
   172	                }
   173	                throw new WarehouseStorageProcessingFailedException("창고 보관 상태를 판매 완료로 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
   174	            }
   175	        }
   176	    }
   177	
   178	    /**
   179	     * 창고 보관 기간을 연장합니다.
   180	     *
   181	     * @param storageId 창고 보관 ID
   182	     * @param newEndDate 새로운 종료일
   183	     * @param userEmail 요청자 이메일
   184	     * @throws WarehouseStorageNotFoundException 창고 보관 정보를 찾을 수 없을 경우
   185	     * @throws WarehouseStorageAccessDeniedException 접근 권한이 없을 경우
   186	     * @throws StorageExtensionFailedException 기간 연장에 실패한 경우
   187	     */
   188	    @Transactional
   189	    public void extendStoragePeriod(Long storageId, LocalDate newEndDate, String userEmail) {
   190	        if (storageId == null) {
   191	            throw new WarehouseStorageProcessingFailedException("창고 보관 ID가 없습니다.");
   192	        }
   193	        if (newEndDate == null) {
   194	            throw new StorageExtensionFailedException("새로운 종료일이 없습니다.");
   195	        }
   196	        if (newEndDate.isBefore(LocalDate.now())) {
   197	            throw new StorageExtensionFailedException("종료일은 현재 날짜보다 이후여야 합니다.");
   198	        }
   199	
